package entapi

import (
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"strings"
)

// generatedMarker is the ownership marker. Every file this extension writes
// starts with a header containing it (see the first line of each template), so
// the marker is not a record kept alongside the output — it is the output.
//
// It is deliberately narrower than ent's own "Code generated by ent, DO NOT
// EDIT.": matching that would make this extension delete ent's files.
const generatedMarker = "Code generated by entapi extension"

// legacyGeneratedMarker is the marker this extension wrote before the module
// was renamed from entdomain (ADR-0011). Recognition is permanent, not a
// transition window: dropping it would strand every pre-rename consumer tree
// with stale files the build then trips over, and keeping it costs one string
// comparison. The escape hatch is unchanged for both spellings — delete the
// marker line and the file is yours.
const legacyGeneratedMarker = "Code generated by entdomain extension"

// markerScanBytes bounds how much of a file is read looking for its first line.
// Only that first line is searched: the marker is the header, and the header is
// line one of every template. Searching further would let a file that merely
// mentions the marker in a comment or a string be deleted.
const markerScanBytes = 4096

// softDeleteFileName is the one file this extension writes for the graph rather
// than for an entity. It is deliberately not named after any entity: it holds a
// type switch over all of them, so no single node owns it.
//
// The name is prefixed rather than suffixed so it cannot collide with ent's own
// output, which is either a fixed name (ent.go, client.go, mutation.go,
// runtime.go, tx.go) or <entity>_<verb>.go — and no ent entity is called
// "Entapi".
const softDeleteFileName = "entapi_softdelete.go"

// errorMapFileName holds the package-level ErrorMap the wiring returns its
// errors through. It is graph-level for the same reason the wiring needs it to
// be: every entity's wiring lands in the one package, so one declaration serves
// all of them — which is what makes the classification identical across
// operations instead of merely intended to be.
//
// Same prefix rule as above: entapi_ cannot collide with ent's own output.
const errorMapFileName = "entapi_errors.go"

// httpFileName holds the graph-level APIHandler and route manifest.
const httpFileName = "entapi_http.go"

// openapiFileName is the generated OpenAPI 3.1 document — the one artifact this
// extension writes that is not Go source. It is committed with the rest of the
// output, so the exposed surface shows up in a pull request diff.
//
// It is a bare name rather than a prefixed one because it is the file a human
// looks for, and it cannot collide with ent's output, which is Go only.
const openapiFileName = "openapi.yaml"

// openapiEmbedFileName holds the //go:embed of the document above and the
// handler that serves it. Same entapi_ prefix rule as the other graph files.
const openapiEmbedFileName = "entapi_openapi.go"

// removeStaleArtifacts deletes files this extension wrote on an earlier run and
// did not write on this one — the entity lost its annotations, was deleted from
// the schema outright, or the template that produced the file was removed from
// the library.
//
// The marker, not the current schema, decides what may be deleted
// (docs/adr/0004-cleanup-ownership-by-marker.md, #63). Every file this
// extension writes opens with the marker, so a marked file is one it wrote;
// deriving candidate names from the graph instead left a deleted entity's
// output behind, referencing builders ent no longer generates, and told the
// consumer not to edit it. This deletes files from a consumer's repository, so
// both rules have to hold:
//
//  1. Only files carrying the entapi marker on their FIRST line. A
//     hand-written file survives, as does one whose header has been edited into
//     something else, as does every file ent itself generated.
//  2. Never a path this run just wrote.
//
// A consumer who wants to keep a generated file as their own deletes its marker
// line. That is the documented way out (see README.md), and it is an action —
// where the previous rule made keeping stale files the default and removing
// them a manual chore announced by a broken build.
//
// The scan is TOP-LEVEL ONLY and must stay that way: ent generates a
// subpackage per entity below this same directory, plus predicate/, migrate/,
// hook/ and enttest/, and recursing would widen the deletion surface for
// nothing — this extension never writes below the target directory.
//
// Files left in place because of rule 1 are reported rather than silently
// ignored: from the outside they look exactly like output that failed to be
// cleaned up.
func removeStaleArtifacts(dir string, written map[string]bool) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("failed to scan %s for stale generated files: %w", dir, err)
	}
	for _, entry := range entries {
		if entry.IsDir() || !isCleanupCandidate(entry.Name()) {
			continue
		}
		if err := removeIfStale(dir, entry.Name(), written); err != nil {
			return err
		}
	}
	return nil
}

// isCleanupCandidate narrows the scan to the shapes this extension can write.
//
// Everything it emits is Go source, with one exception: openapi.yaml (#76).
// Before that exception existed the scan was `.go`-suffixed, which would have
// left a stale document alive in a consumer's tree forever — no run would ever
// have considered it.
//
// The exception is an EXACT NAME, not a `.yaml` suffix class. Widening it to
// every YAML file would put a consumer's own marked document — a checked-in
// golden copy, a hand-maintained spec quoting a generated header — inside the
// deletion surface for no gain, since this extension writes exactly one.
func isCleanupCandidate(name string) bool {
	return strings.HasSuffix(name, ".go") || name == openapiFileName
}

// removeIfStale applies both rules to one candidate path.
func removeIfStale(dir, name string, written map[string]bool) error {
	path := filepath.Join(dir, name)
	if written[path] {
		return nil
	}

	owned, err := hasGeneratedMarker(path)
	if err != nil {
		return err
	}
	if !owned {
		return nil
	}

	if err := os.Remove(path); err != nil {
		return fmt.Errorf("failed to remove stale generated file %s: %w", path, err)
	}
	log.Printf("entapi: removed stale generated file %s (no longer generated this run)", path)
	return nil
}

// hasGeneratedMarker reports whether path exists and carries the entapi
// marker on its first line. A file that exists without it is reported as not
// ours, on the log, and left alone.
func hasGeneratedMarker(path string) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("failed to inspect %s: %w", path, err)
	}
	defer func() { _ = f.Close() }()

	head := make([]byte, markerScanBytes)
	n, err := f.Read(head)
	if err != nil && err != io.EOF {
		return false, fmt.Errorf("failed to inspect %s: %w", path, err)
	}
	firstLine, _, _ := strings.Cut(string(head[:n]), "\n")
	if strings.Contains(firstLine, generatedMarker) || strings.Contains(firstLine, legacyGeneratedMarker) {
		return true, nil
	}

	log.Printf("entapi: leaving %s in place — it does not carry the %q header, so this extension did not write it", path, generatedMarker)
	return false, nil
}
